<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Payment extends Model{protected $fillable=['tenant_id','amount','paid_at','period','billing_cycle','period_count','method','recorded_by'];protected $casts=['paid_at'=>'date','amount'=>'decimal:2','period_count'=>'integer'];public function tenant(){return $this->belongsTo(Tenant::class);}public function recorder(){return $this->belongsTo(User::class,'recorded_by');}}
